// ============================================================================
// IO_LINK_apb: APB4 register wrapper around IO_LINK_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/IO_LINK.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/IO_LINK.md
// ============================================================================
module IO_LINK_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic txd,
  output logic tx_en,
  input logic rxd
);
  localparam logic [31:0] ID_VALUE = 32'h10C90100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [14:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd15) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_cfg_master;
  logic [15:0]   c_cfg_bit;
  logic [15:0]   c_cfg_wurq;
  logic [1:0]    c_cfg_mtype;
  logic [5:0]    c_cfg_pdout_len;
  logic [5:0]    c_cfg_pdin_len;
  logic [5:0]    c_cfg_od_len;
  logic          c_host_rd;
  logic          c_host_wr;
  logic [7:0]    c_host_addr;
  logic [7:0]    c_host_wdata;
  logic [7:0]    c_host_rdata;
  logic [7:0]    c_cfg_resp_timeout;
  logic          c_m_wurq;
  logic          c_m_start;
  logic [7:0]    c_m_mc;
  logic          c_m_busy;
  logic          c_m_done;
  logic          c_m_err_timeout;
  logic          c_m_err_uart;
  logic          c_m_err_cks;
  logic [7:0]    c_m_cks;
  logic [6:0]    c_m_cnt;
  logic [3:0]    c_cfg_ta;
  logic          c_cfg_event;
  logic          c_cfg_pd_invalid;
  logic          c_d_wurq;
  logic          c_d_msg;
  logic [7:0]    c_d_msg_mc;
  logic [2:0]    c_d_msg_why;
  IO_LINK_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cfg_master(c_cfg_master),
    .cfg_bit(c_cfg_bit),
    .cfg_wurq(c_cfg_wurq),
    .cfg_mtype(c_cfg_mtype),
    .cfg_pdout_len(c_cfg_pdout_len),
    .cfg_pdin_len(c_cfg_pdin_len),
    .cfg_od_len(c_cfg_od_len),
    .txd(txd),
    .tx_en(tx_en),
    .rxd(rxd),
    .host_rd(c_host_rd),
    .host_wr(c_host_wr),
    .host_addr(c_host_addr),
    .host_wdata(c_host_wdata),
    .host_rdata(c_host_rdata),
    .cfg_resp_timeout(c_cfg_resp_timeout),
    .m_wurq(c_m_wurq),
    .m_start(c_m_start),
    .m_mc(c_m_mc),
    .m_busy(c_m_busy),
    .m_done(c_m_done),
    .m_err_timeout(c_m_err_timeout),
    .m_err_uart(c_m_err_uart),
    .m_err_cks(c_m_err_cks),
    .m_cks(c_m_cks),
    .m_cnt(c_m_cnt),
    .cfg_ta(c_cfg_ta),
    .cfg_event(c_cfg_event),
    .cfg_pd_invalid(c_cfg_pd_invalid),
    .d_wurq(c_d_wurq),
    .d_msg(c_d_msg),
    .d_msg_mc(c_d_msg_mc),
    .d_msg_why(c_d_msg_why)
  );

  // ---------------- registers ----------------
  logic [3:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [8:0] r_CTRL;   // 12'h014 CTRL
  logic [31:0] r_TIMING;   // 12'h018 TIMING
  logic [25:0] r_LENGTHS;   // 12'h01C LENGTHS
  logic [7:0] r_MC;   // 12'h020 MC
  logic [7:0] r_MEM_ADDR;   // 12'h024 MEM_ADDR
  logic [7:0] r_MEM_WDATA;   // 12'h028 MEM_WDATA
  logic [3:0] p_CMD;   // 12'h02C CMD (pulses)
  logic [10:0] h_D_MSG;   // 12'h038 D_MSG holding register
  logic avail_D_MSG;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 9'h10;
      r_TIMING <= 32'hFA000D9;
      r_LENGTHS <= 26'h401000;
      r_MC <= 8'h0;
      r_MEM_ADDR <= 8'h0;
      r_MEM_WDATA <= 8'h0;
      p_CMD <= '0;
      h_D_MSG <= '0;
      avail_D_MSG <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[3:0] & wmask[3:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[6]) r_TIMING <= (r_TIMING & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_LENGTHS <= (r_LENGTHS & ~wmask[25:0]) | (PWDATA[25:0] & wmask[25:0]);
      if (wr && hit[8]) r_MC <= (r_MC & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[9]) r_MEM_ADDR <= (r_MEM_ADDR & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[10]) r_MEM_WDATA <= (r_MEM_WDATA & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      p_CMD <= (wr && hit[11]) ? PWDATA[3:0] & wmask[3:0] : '0;
      if (c_d_msg && (!avail_D_MSG || (rd && hit[14]))) begin
        h_D_MSG[7:0] <= c_d_msg_mc[7:0];
        h_D_MSG[10:8] <= c_d_msg_why[2:0];
        avail_D_MSG <= 1'b1;
      end else if (rd && hit[14]) avail_D_MSG <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cfg_master = r_CTRL[0:0];
  assign c_cfg_mtype = r_CTRL[2:1];
  assign c_cfg_ta = r_CTRL[6:3];
  assign c_cfg_event = r_CTRL[7:7];
  assign c_cfg_pd_invalid = r_CTRL[8:8];
  assign c_cfg_bit = r_TIMING[15:0];
  assign c_cfg_wurq = r_TIMING[31:16];
  assign c_cfg_pdout_len = r_LENGTHS[5:0];
  assign c_cfg_pdin_len = r_LENGTHS[11:6];
  assign c_cfg_od_len = r_LENGTHS[17:12];
  assign c_cfg_resp_timeout = r_LENGTHS[25:18];
  assign c_m_mc = r_MC[7:0];
  assign c_host_addr = r_MEM_ADDR[7:0];
  assign c_host_wdata = r_MEM_WDATA[7:0];
  assign c_m_start = p_CMD[0:0];
  assign c_m_wurq = p_CMD[1:1];
  assign c_host_wr = p_CMD[2:2];
  assign c_host_rd = p_CMD[3:3];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_m_done;
    irq_set[1] = c_d_wurq;
    irq_set[2] = c_d_msg & (~avail_D_MSG | (rd & hit[14]));
    irq_set[3] = c_d_msg & avail_D_MSG & ~(rd & hit[14]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [0:0] flags = {avail_D_MSG};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_TIMING);
      10'd7: apb_rdata = 32'(r_LENGTHS);
      10'd8: apb_rdata = 32'(r_MC);
      10'd9: apb_rdata = 32'(r_MEM_ADDR);
      10'd10: apb_rdata = 32'(r_MEM_WDATA);
      10'd12: apb_rdata = 32'({c_host_rdata});
      10'd13: apb_rdata = 32'({c_m_cnt, c_m_cks, c_m_err_cks, c_m_err_uart, c_m_err_timeout, c_m_busy});
      10'd14: apb_rdata = 32'(h_D_MSG);
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
